func restartPins(dir int, uid, gid uint32, accepted AcceptedIdentity, roots trust.Keyring,
) (MaterialPins, error) {
	target, err := generationTarget(accepted)
	if err != nil {
		return MaterialPins{}, err
	}
	acceptedWire, err := EncodeAcceptedIdentity(accepted)
	if err != nil {
		return MaterialPins{}, err
	}
	digests := acceptedMaterialDigests(accepted)
	wire, err := readUnpinned(dir, MaterialGenerationsFile, uid, gid,
		bootstrap.MaxMaterialGenerations*(bootstrap.MaxMaterialGenerationBytes+16<<10))
	if errors.Is(err, os.ErrNotExist) {
		if accepted.MaterialGenerationSHA256 != "" {
			return MaterialPins{}, fmt.Errorf("%w: accepted generation chain is missing", ErrMaterial)
		}
		return MaterialPins{Digests: digests, slot: accepted.Slot, acceptance: target.AcceptanceSHA256, acceptedSHA256: digest(acceptedWire), references: accepted.MaterialReferences}, nil
	}
	if err != nil {
		return MaterialPins{}, fmt.Errorf("read adopted material generations: %w", err)
	}
	chain, err := bootstrap.DecodeMaterialGenerationChain(wire)
	if err != nil {
		return MaterialPins{}, err
	}
	verified, err := target.VerifyAdoptedChain(chain, roots)
	if err != nil {
		return MaterialPins{}, fmt.Errorf("verify adopted material generations: %w", err)
	}
	return pinsFromGeneration(accepted, verified[len(verified)-1], wire)
}

func pinsFromGeneration(accepted AcceptedIdentity, newest bootstrap.VerifiedMaterialGeneration, wire []byte) (MaterialPins, error) {
	target, err := generationTarget(accepted)
	if err != nil {
		return MaterialPins{}, err
	}
	acceptedWire, err := EncodeAcceptedIdentity(accepted)
	if err != nil {
		return MaterialPins{}, err
	}
	digests := acceptedMaterialDigests(accepted)
	pins := MaterialPins{Digests: map[string]string{}, Issued: map[string]string{}, Generation: &newest,
		slot: accepted.Slot, acceptance: target.AcceptanceSHA256, acceptedSHA256: digest(acceptedWire), references: accepted.MaterialReferences, target: target,
		identity: bootstrapmaterial.ControllerLeafIdentity(strings.ToLower(accepted.Cell), accepted.Slot, accepted.PrimaryPrivateIP)}
	maps.Copy(pins.Digests, digests)
	generation := newest.Generation()
	for _, name := range bootstrapmaterial.IssuedFiles(accepted.Slot) {
		if digests[name] == "" {
			return MaterialPins{}, fmt.Errorf("%w: issued file %s is not part of this install", ErrMaterial, name)
		}
		if generation.AccountSigner != "" {
			pins.Issued[name] = digests[name]
			delete(pins.Digests, name)
		}
	}
	for _, secret := range generation.Secrets {
		if secret.Slot == "" || secret.Slot == accepted.Slot {
			pins.Digests[secret.TargetFile] = secret.SHA256
		}
	}
	pins.Digests[MaterialGenerationsFile] = digest(wire)
	return pins, nil
}

func (pins MaterialPins) matchesAccepted(accepted AcceptedIdentity) bool {
	wire, err := EncodeAcceptedIdentity(accepted)
	return err == nil && pins.acceptedSHA256 == digest(wire)
}

// controllerConfigSHA256 is the controller config digest a restart of the
// accepted slot expects: the newest adopted generation's config, bound to the
// acyclic acceptance digest, or the accepted baseline config.
func (pins MaterialPins) controllerConfigSHA256(accepted AcceptedIdentity) (string, error) {
	acceptance, err := accepted.AcceptanceSHA256()
	if err != nil || pins.acceptance != acceptance || !pins.matchesAccepted(accepted) {
		return "", ErrMaterial
	}
	if pins.Generation != nil {
		for _, config := range pins.Generation.Generation().ControllerConfigs {
			if config.Slot == accepted.Slot {
				if config.AcceptanceSHA256 != acceptance {
					return "", fmt.Errorf("%w: controller config is bound to another acceptance", ErrMaterial)
				}
				return config.SHA256, nil
			}
		}
	}
	return accepted.ConfigSHA256["controller.json"], nil
}

func acceptedMaterialDigests(accepted AcceptedIdentity) map[string]string {
	digests := make(map[string]string, len(accepted.MaterialReferences))
	for _, reference := range accepted.MaterialReferences {
		digests[reference.TargetFile] = reference.SHA256
	}
	return digests
}

// verifyGeneration checks the newest generation's pinned files again at now,
// with the rules they were signed under (CA bundle, issuers, JWTs, system
// credentials, interregion files and the loaded controller config, all
// current), then the slot's issued files.
func (pins MaterialPins) verifyGeneration(dir int, uid, gid uint32, now time.Time) error {
	if pins.Generation == nil {
		return nil
	}
	// The generation is the authority for its material: past its signed
	// expiry the owner must sign the next one before accepted restart.
	if !now.Before(pins.Generation.ExpiresAt()) {
		return fmt.Errorf("%w: the adopted material generation expired at %s", ErrMaterial,
			pins.Generation.ExpiresAt().Format(time.RFC3339))
	}
	if err := pins.target.VerifyFiles(pins.Generation.Generation(), func(name string) ([]byte, error) {
		if name == "controller-"+pins.slot+".json" {
			return pins.config, nil
		}
		if pins.Digests[name] == "" {
			// Another slot's leaf TLS or config: never held here.
			return nil, fs.ErrNotExist
		}
		return readMaterial(dir, name, uid, gid, pins.Digests[name], bootstrap.MaxSecretBytes)
	}, now); err != nil {
		return fmt.Errorf("%w: adopted material generation: %w", ErrMaterial, err)
	}
	return pins.verifyIssued(dir, uid, gid, now)
}

// verifyIssued checks the slot's issued files against the newest generation,
// whose pinned issuer and bundle are read from the same directory. Without
// controller issuers they are pinned by digest instead.
func (pins MaterialPins) verifyIssued(dir int, uid, gid uint32, now time.Time) error {
	if pins.Generation == nil || len(pins.Issued) == 0 {
		return nil
	}
	files := map[string][]byte{}
	defer func() {
		for _, content := range files {
			clear(content)
		}
	}()
	for name := range pins.Issued {
		content, err := readUnpinned(dir, name, uid, gid, bootstrap.MaxSecretBytes)
		if err != nil {
			return fmt.Errorf("read issued %s: %w", name, err)
		}
		files[name] = content
	}
	for _, name := range []string{"controller-tls-issuer-cert.pem", "ca.pem"} {
		content, err := readMaterial(dir, name, uid, gid, pins.Digests[name], bootstrap.MaxSecretBytes)
		if err != nil {
			return fmt.Errorf("read generation %s: %w", name, err)
		}
		files[name] = content
	}
	return pins.verifyIssuedFiles(files, now)
}

func (pins MaterialPins) verifyIssuedFiles(files map[string][]byte, now time.Time) error {
	if pins.Generation == nil || len(pins.Issued) == 0 {
		return nil
	}
	generation := pins.Generation.Generation()
	names := bootstrapmaterial.IssuedFiles(pins.slot)
	certName, keyName, credsName := names[0], names[1], names[2]
	original := func(name string) bool { return digest(files[name]) == pins.Issued[name] }
	if !original(certName) || !original(keyName) {
		if err := bootstrapmaterial.CheckIssuedTLS(generation, files["controller-tls-issuer-cert.pem"], files["ca.pem"],
			files[certName], files[keyName], pins.identity, now); err != nil {
			return fmt.Errorf("%w: %w", ErrMaterial, err)
		}
	}
	if !original(credsName) {
		if err := bootstrapmaterial.CheckIssuedCredentials(generation, files[credsName], now); err != nil {
			return fmt.Errorf("%w: %w", ErrMaterial, err)
		}
	}
	return nil
}

// readUnpinned reads a service-owned credential file whose digest is not
// pinned, with readMaterial's ownership, mode, link and size checks.
func readUnpinned(dir int, name string, uid, gid uint32, maximum int64) ([]byte, error) {
	if !markerNameRE.MatchString(name) || maximum <= 0 {
		return nil, ErrMaterial
	}
	fd, err := unix.Openat(dir, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != uid || stat.Gid != gid || stat.Mode&0o777 != 0o600 || stat.Nlink != 1 ||
		stat.Size <= 0 || stat.Size > maximum {
		return nil, ErrMaterial
	}
	content, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil || len(content) == 0 || int64(len(content)) > maximum {
		clear(content)
		return nil, ErrMaterial
	}
	return content, nil
}

func (store MaterialStore) RestartPins(accepted AcceptedIdentity, roots trust.Keyring,
) (MaterialPins, error) {
	installed, err := openMaterialDirectory(store.installedDirectory, store.serviceUID, store.serviceGID, 0o700, store.allowUnsafeAncestors)
	if err != nil {
		return MaterialPins{}, fmt.Errorf("open service-owned credential directory: %w", err)
	}
	defer unix.Close(installed)
	return restartPins(installed, store.serviceUID, store.serviceGID, accepted, roots)
}

// ControllerConfigSHA256 reads the install's adopted material generation, if
// any, and returns the controller config digest restart admission expects
// for the accepted slot.
func (store MaterialStore) ControllerConfigSHA256(accepted AcceptedIdentity, roots trust.Keyring,
) (string, error) {
	installed, err := openMaterialDirectory(store.installedDirectory, store.serviceUID, store.serviceGID, 0o700, store.allowUnsafeAncestors)
	if err != nil {
		return "", fmt.Errorf("open service-owned credential directory: %w", err)
	}
	defer unix.Close(installed)
	pins, err := restartPins(installed, store.serviceUID, store.serviceGID, accepted, roots)
	if err != nil {
		return "", err
	}
	return pins.controllerConfigSHA256(accepted)
}

func (store MaterialStore) VerifyRestart(ctx context.Context, accepted AcceptedIdentity,
	pins MaterialPins,
) error {
	acceptance, err := accepted.AcceptanceSHA256()
	if err != nil || pins.acceptance != acceptance || !pins.matchesAccepted(accepted) ||
		pins.Generation == nil && !sameMaterials(acceptedMaterialDigests(accepted), pins.Digests) {
		return ErrMaterial
	}
	installed, err := openMaterialDirectory(store.installedDirectory, store.serviceUID, store.serviceGID, 0o700, store.allowUnsafeAncestors)
	if err != nil {
		return fmt.Errorf("open service-owned credential directory: %w", err)
	}
	defer unix.Close(installed)
	if err := store.verifyInstalled(ctx, installed, pins.Digests); err != nil {
		return err
	}
	return pins.verifyGeneration(installed, store.serviceUID, store.serviceGID, time.Now())
}

func (store MaterialStore) verifyInstalled(ctx context.Context, dir int, expected map[string]string) error {
	for name, want := range expected {
		if err := ctx.Err(); err != nil {
			return err
		}
		content, err := readMaterial(dir, name, store.serviceUID, store.serviceGID, want, bootstrap.MaxSecretBytes)
		if err != nil {
			return fmt.Errorf("verify installed secret %s: %w", name, err)
		}
		clear(content)
	}
	return nil
}

func readMaterial(dir int, name string, uid, gid uint32, want string, maximum int64) ([]byte, error) {
	if !markerNameRE.MatchString(name) || !markerDigestRE.MatchString(want) || maximum <= 0 || maximum > bootstrap.MaxSecretBytes {
		return nil, ErrMaterial
	}
	fd, err := unix.Openat(dir, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != uid || stat.Gid != gid || stat.Mode&0o777 != 0o600 || stat.Nlink != 1 ||
		stat.Size <= 0 || stat.Size > maximum {
		return nil, ErrMaterial
	}
	content, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil || len(content) == 0 || int64(len(content)) > maximum || digest(content) != want {
		clear(content)
		return nil, ErrMaterial
	}
	return content, nil
}

func openMaterialDirectory(path string, uid, gid uint32, mode uint32, allowUnsafeAncestors bool) (int, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return -1, ErrMaterial
	}
	fd, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return -1, err
	}
	components := strings.Split(strings.TrimPrefix(path, "/"), "/")
	for index, component := range components {
		if component == "" || component == "." || component == ".." {
			unix.Close(fd)
			return -1, ErrMaterial
		}
		next, err := unix.Openat(fd, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
		unix.Close(fd)
		if err != nil {
			return -1, err
		}
		fd = next
		var stat unix.Stat_t
		if err := unix.Fstat(fd, &stat); err != nil ||
			index < len(components)-1 && !allowUnsafeAncestors && (stat.Uid != 0 || stat.Mode&0o022 != 0) {
			unix.Close(fd)
			return -1, ErrMaterial
		}
	}
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Uid != uid || stat.Gid != gid || stat.Mode&0o777 != mode {
		unix.Close(fd)
		return -1, ErrMaterial
	}
	return fd, nil
}

func (check LiveCredentials) verifyPaths(expected MaterialPins, slot, seedSlot string, references []bootstrap.SecretReference) error {
	if slot == "" || seedSlot == "" {
		return ErrLiveCredentials
	}
	e := check.Config.Embedded
	paths := []string{
		check.Config.CredentialsFile,
		check.Config.TLS.CAFile, check.Config.TLS.CertFile, check.Config.TLS.KeyFile,
		e.TLS.CAFile, e.TLS.CertFile, e.TLS.KeyFile,
		e.RouteTLS.CAFile, e.RouteTLS.CertFile, e.RouteTLS.KeyFile,
		e.OperatorJWTFile, e.SystemJWTFile, e.CellJWTFile, e.SystemCredentialsFile,
		e.TicketPublicKeyFile,
	}
	if e.RoutePasswordFile != "" {
		paths = append(paths, e.RoutePasswordFile)
	}
	// The optional scoped membership user is signed material like every
	// other credential: when configured it must be pinned, and when signed
	// it must be configured.
	if e.MembershipCredentialsFile != "" {
		paths = append(paths, e.MembershipCredentialsFile)
	}
	paths = append(paths, check.ResponseKeyFile, check.BrokerTicketKeyFile,
		check.HostNATSIssuerSeedFile, check.HostTLSIssuerKeyFile, check.HostTLSIssuerCertFile)
	if check.HostNATSIssuerSeedFile != filepath.Join(check.directory, "host-nats-issuer.seed") ||
		check.HostTLSIssuerKeyFile != filepath.Join(check.directory, "host-tls-issuer-key.pem") ||
		check.HostTLSIssuerCertFile != filepath.Join(check.directory, "host-tls-issuer-cert.pem") {
		return fmt.Errorf("%w: host issuer paths differ from fixed roles", ErrLiveCredentials)
	}
	// The member CA follows the membership rule: pinned when configured, and
	// the inventory loop below requires it configured when signed.
	if check.TerraBaseCACertFile != "" || check.TerraBaseCAKeyFile != "" {
		if check.TerraBaseCACertFile != filepath.Join(check.directory, "terrabase-member-ca.pem") ||
			check.TerraBaseCAKeyFile != filepath.Join(check.directory, "terrabase-member-ca.key") {
			return fmt.Errorf("%w: TerraBase member CA paths differ from fixed roles", ErrLiveCredentials)
		}
		paths = append(paths, check.TerraBaseCACertFile, check.TerraBaseCAKeyFile)
	}
	// Interregion and link files must belong to the accepted baseline or adopted generation.
	for _, path := range append(e.InterRegion.Files(), e.Link.Files()...) {
		if !expected.interRegion(filepath.Base(path)) {
			return fmt.Errorf("%w: interregion or link credential path is not pinned by the adopted generation", ErrLiveCredentials)
		}
		paths = append(paths, path)
	}
	seen := make(map[string]bool, len(paths))
	for _, path := range paths {
		name := filepath.Base(path)
		if path == "" || path != filepath.Join(check.directory, name) || !expected.known(name) {
			return fmt.Errorf("%w: configured credential path is not pinned by signed material", ErrLiveCredentials)
		}
		seen[name] = true
	}
	if slot == seedSlot {
		purposes := make(map[bootstrap.SecretPurpose]bool, 2)
		for _, reference := range references {
			if reference.Purpose != bootstrap.SecretSeedFounder &&
				reference.Purpose != bootstrap.SecretSeedLedgerSigner {
				continue
			}
			name := reference.TargetFile
			if reference.Slot != seedSlot || name == "" ||
				filepath.Base(name) != name || expected.Digests[name] == "" ||
				expected.Digests[name] != reference.SHA256 || seen[name] || purposes[reference.Purpose] {
				return fmt.Errorf("%w: seed signer is not pinned to its signed role and slot", ErrLiveCredentials)
			}
			seen[name] = true
			purposes[reference.Purpose] = true
		}
		if len(purposes) != 0 && (!purposes[bootstrap.SecretSeedFounder] || !purposes[bootstrap.SecretSeedLedgerSigner]) {
			return fmt.Errorf("%w: signed seed signer roles are incomplete", ErrLiveCredentials)
		}
	}
	// A generation's own files have their role in the generation: the chain,
	// and the controller issuers the renewal loop reads by fixed name.
	for name := range expected.Digests {
		if !seen[name] && (!generationOwnFile(name)) {
			return fmt.Errorf("%w: signed credential material has no configured role", ErrLiveCredentials)
		}
	}
	for name := range expected.Issued {
		if !seen[name] {
			return fmt.Errorf("%w: issued credential material has no configured role", ErrLiveCredentials)
		}
	}
	return nil
}

func (check LiveCredentials) verifyInitialPaths(expected MaterialPins, manifest bootstrap.Manifest) error {
	expected.references = slotReferences(manifest, manifest.Slot)
	return check.verifyPaths(expected, manifest.Slot, manifest.SeedSlot, manifest.Secrets)
}

func generationOwnFile(name string) bool {
	return name == MaterialGenerationsFile ||
		bootstrap.MaterialGenerationFiles()[name] == bootstrap.SecretControllerIssuer
}

func (check LiveCredentials) verifyInventory(expected MaterialPins) error {
	dir, err := openMaterialDirectory(check.directory, check.ServiceUID, check.ServiceGID, 0o700, check.allowUnsafeAncestors)
	if err != nil {
		return fmt.Errorf("%w: open fixed credential directory: %v", ErrLiveCredentials, err)
	}
	defer unix.Close(dir)
	copyFD, err := unix.Dup(dir)
	if err != nil {
		return err
	}
	file := os.NewFile(uintptr(copyFD), check.directory)
	entries, err := file.ReadDir(-1)
	_ = file.Close()
	if err != nil || len(entries) != expected.size() {
		return fmt.Errorf("%w: installed credential inventory differs", ErrLiveCredentials)
	}
	for _, entry := range entries {
		if !expected.known(entry.Name()) {
			return fmt.Errorf("%w: unpinned credential file", ErrLiveCredentials)
		}
		var content []byte
		var err error
		if want := expected.Digests[entry.Name()]; want != "" {
			content, err = readMaterial(dir, entry.Name(), check.ServiceUID, check.ServiceGID, want, bootstrap.MaxSecretBytes)
		} else {
			// Issued files were checked by rule in VerifyRestart.
			content, err = readUnpinned(dir, entry.Name(), check.ServiceUID, check.ServiceGID, bootstrap.MaxSecretBytes)
		}
		if err != nil {
			return fmt.Errorf("%w: installed credential %s: %v", ErrLiveCredentials, entry.Name(), err)
		}
		clear(content)
	}
	return nil
}

func IssuedFiles(slot string) []string {
	return []string{slot + "-tls-cert.pem", slot + "-tls-key.pem", slot + ".creds"}
}

// LeafIdentity is the subject and names of one controller slot's TLS leaf.
type LeafIdentity struct {
	CommonName string
	DNSName    string
	IP         string
}

// ControllerLeafIdentity is the identity bootstrap material gives a slot.
func ControllerLeafIdentity(cell, slot, privateIP string) LeafIdentity {
	return LeafIdentity{CommonName: naming.NATSServer(cell, slot), DNSName: slot, IP: privateIP}
}

// ControllerIssuer is a generation's online issuing material, which every
// controller holds: the controller TLS issuer and the cell account signer.
type ControllerIssuer struct {
	identity issuerIdentity
	certPEM  []byte
	cert     *x509.Certificate
	key      *ecdsa.PrivateKey
	signer   nkeys.KeyPair
}

type issuerIdentity struct {
	Cell, Environment, Operator, CellAccount, AccountSigner string
	lifetime                                                time.Duration
	expiresAt                                               time.Time
}

// LoadControllerIssuer parses the generation's controller-tls-issuer-cert.pem,
// controller-tls-issuer-key.pem and controller-account-signer.seed, which
// CheckGenerationFiles has already verified against the generation.
func LoadControllerIssuer(generation bootstrap.MaterialGeneration, certPEM, keyPEM, signerSeed []byte,
) (*ControllerIssuer, error) {
	return loadControllerIssuer(issuerIdentity{Cell: string(generation.Cell), Environment: generation.Environment,
		Operator: generation.Operator, CellAccount: generation.CellAccount, AccountSigner: generation.AccountSigner,
		lifetime: time.Duration(generation.IssuedLifetimeHours) * time.Hour}, certPEM, keyPEM, signerSeed)
}

func loadControllerIssuer(identity issuerIdentity, certPEM, keyPEM, signerSeed []byte) (*ControllerIssuer, error) {
	block, _ := pem.Decode(certPEM)
	if block == nil {
		return nil, errors.New("controller TLS issuer certificate is invalid")
	}
	cert, err := x509.ParseCertificate(block.Bytes)
	if err != nil {
		return nil, fmt.Errorf("controller TLS issuer certificate: %w", err)
	}
	if identity.expiresAt.IsZero() || cert.NotAfter.Before(identity.expiresAt) {
		identity.expiresAt = cert.NotAfter
	}
	keyBlock, _ := pem.Decode(keyPEM)
	if keyBlock == nil {
		return nil, errors.New("controller TLS issuer key is invalid")
	}
	key, err := x509.ParseECPrivateKey(keyBlock.Bytes)
	if err != nil {
		return nil, fmt.Errorf("controller TLS issuer key: %w", err)
	}
	signer, err := nkeys.FromSeed([]byte(strings.TrimSpace(string(signerSeed))))
	if err != nil {
		return nil, errors.New("controller account signer seed is invalid")
	}
	if public, err := signer.PublicKey(); err != nil || public != identity.AccountSigner {
		signer.Wipe()
		return nil, errors.New("controller account signer differs from the generation's")
	}
	return &ControllerIssuer{identity: identity, certPEM: pem.EncodeToMemory(block), cert: cert, key: key,
		signer: signer}, nil
}

// Wipe clears the account signer seed.
func (issuer *ControllerIssuer) Wipe() { issuer.signer.Wipe() }

func (issuer *ControllerIssuer) lifetime() time.Duration {
	return issuer.identity.lifetime
}

// RenewTLS issues a leaf with identity and a fresh key, valid for the
// generation's issued lifetime and never past the issuer. certPEM holds the
// leaf followed by the issuer, so peers can build the chain to the bundle.
func (issuer *ControllerIssuer) RenewTLS(identity LeafIdentity, now time.Time) (certPEM, keyPEM []byte, err error) {
	if issuer == nil || issuer.cert == nil || issuer.key == nil || !now.Before(issuer.identity.expiresAt) {
		return nil, nil, errors.New("controller TLS issuer has expired")
	}
	ip := net.ParseIP(identity.IP)
	if identity.CommonName == "" || identity.DNSName == "" || ip == nil {
		return nil, nil, errors.New("controller leaf identity is incomplete")
	}
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, nil, err
	}
	serial, err := rand.Int(rand.Reader, new(big.Int).Lsh(big.NewInt(1), 128))
	if err != nil {
		return nil, nil, err
	}
	notAfter := now.Add(issuer.lifetime() - issuedBackdate)
	if notAfter.After(issuer.identity.expiresAt) {
		notAfter = issuer.identity.expiresAt
	}
	template := &x509.Certificate{SerialNumber: serial, Subject: pkix.Name{CommonName: identity.CommonName},
		NotBefore: now.Add(-issuedBackdate), NotAfter: notAfter, KeyUsage: x509.KeyUsageDigitalSignature,
		ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth},
		IPAddresses: []net.IP{ip}, DNSNames: []string{identity.DNSName}}
	der, err := x509.CreateCertificate(rand.Reader, template, issuer.cert, &key.PublicKey, issuer.key)
	if err != nil {
		return nil, nil, err
	}
	keyDER, err := x509.MarshalECPrivateKey(key)
	if err != nil {
		return nil, nil, err
	}
	leaf := pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der})
	return append(leaf, issuer.certPEM...), pem.EncodeToMemory(&pem.Block{Type: "EC PRIVATE KEY", Bytes: keyDER}), nil
}

// RenewCredentials re-signs the user JWT of current credentials, keeping its
// user key and grants, under the account signer for the generation's issued
// lifetime. A NATS JWT is always stamped with the wall clock, so the lifetime
// starts now.
func (issuer *ControllerIssuer) RenewCredentials(current []byte) ([]byte, error) {
	if issuer == nil || issuer.cert == nil || issuer.signer == nil || !time.Now().Before(issuer.identity.expiresAt) {
		return nil, errors.New("controller account issuer has expired")
	}
	raw, err := jwt.ParseDecoratedJWT(current)
	if err != nil {
		return nil, err
	}
	claims, err := jwt.DecodeUserClaims(raw)
	if err != nil {
		return nil, err
	}
	user, err := jwt.ParseDecoratedUserNKey(current)
	if err != nil {
		return nil, err
	}
	defer user.Wipe()
	if public, err := user.PublicKey(); err != nil || public != claims.Subject {
		return nil, errors.New("controller credential seed and user JWT differ")
	}
	seed, err := user.Seed()
	if err != nil {
		return nil, err
	}
	defer clear(seed)
	claims.IssuerAccount = issuer.identity.CellAccount
	// Encode stamps IssuedAt with the wall clock (nats-io/jwt claims.go), so
	// Expires is set from the same clock just before.
	claims.Expires = minTime(time.Now().Add(issuer.lifetime()-issuedBackdate), issuer.identity.expiresAt).Unix()
	claims.NotBefore = 0
	encoded, err := claims.Encode(issuer.signer)
	if err != nil {
		return nil, err
	}
	return jwt.FormatUserConfig(encoded, seed)
}

// CheckIssuedTLS checks a slot's TLS leaf issued under generation: the
// certificate file holds the leaf and the generation's controller issuer;
// the issuer signed the leaf and chains to bundle; the leaf is a server and
// client leaf with exactly identity, a lifetime within the generation's,
// current at now, and its key matches.
func CheckIssuedTLS(generation bootstrap.MaterialGeneration, issuerPEM, bundlePEM, certPEM, keyPEM []byte,
	identity LeafIdentity, now time.Time,
) error {
	var blocks []*pem.Block
	for rest := certPEM; ; {
		var block *pem.Block
		if block, rest = pem.Decode(rest); block == nil {
			if len(bytes.TrimSpace(rest)) != 0 {
				return errors.New("issued TLS leaf has trailing data")
			}
			break
		}
		blocks = append(blocks, block)
	}
	issuerBlock, _ := pem.Decode(issuerPEM)
	if len(blocks) != 2 || blocks[0].Type != "CERTIFICATE" || issuerBlock == nil ||
		!bytes.Equal(blocks[1].Bytes, issuerBlock.Bytes) {
		return errors.New("issued TLS leaf must be followed by exactly the generation's controller issuer")
	}
	leaf, err := x509.ParseCertificate(blocks[0].Bytes)
	if err != nil {
		return fmt.Errorf("issued TLS leaf: %w", err)
	}
	issuer, err := x509.ParseCertificate(issuerBlock.Bytes)
	if err != nil {
		return fmt.Errorf("controller TLS issuer: %w", err)
	}
	roots := x509.NewCertPool()
	if !roots.AppendCertsFromPEM(bundlePEM) {
		return errors.New("generation CA bundle is invalid")
	}
	intermediates := x509.NewCertPool()
	intermediates.AddCert(issuer)
	for _, usage := range []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth} {
		if _, err := leaf.Verify(x509.VerifyOptions{Roots: roots, Intermediates: intermediates, CurrentTime: now,
			KeyUsages: []x509.ExtKeyUsage{usage}}); err != nil {
			return fmt.Errorf("issued TLS leaf does not chain to the generation: %w", err)
		}
	}
	lifetime := time.Duration(generation.IssuedLifetimeHours) * time.Hour
	if leaf.CheckSignatureFrom(issuer) != nil || leaf.IsCA || leaf.Subject.CommonName != identity.CommonName ||
		!slices.Equal(leaf.DNSNames, []string{identity.DNSName}) || len(leaf.IPAddresses) != 1 ||
		!leaf.IPAddresses[0].Equal(net.ParseIP(identity.IP)) || len(leaf.URIs) != 0 || len(leaf.EmailAddresses) != 0 ||
		leaf.NotAfter.Sub(leaf.NotBefore) > lifetime {
		return errors.New("issued TLS leaf has another identity or a longer lifetime than the generation allows")
	}
	keyBlock, rest := pem.Decode(keyPEM)
	if keyBlock == nil || keyBlock.Type != "EC PRIVATE KEY" || len(bytes.TrimSpace(rest)) != 0 {
		return errors.New("issued TLS key format is invalid")
	}
	key, err := x509.ParseECPrivateKey(keyBlock.Bytes)
	public, isECDSA := leaf.PublicKey.(*ecdsa.PublicKey)
	if err != nil || !isECDSA || !public.Equal(&key.PublicKey) {
		return errors.New("issued TLS key does not match its leaf")
	}
	return nil
}

// CheckIssuedCredentials checks a controller's NATS credentials issued under
// generation: the seed matches the user JWT, which the account signer issued
// for the cell account with a lifetime within the generation's, current at
// now. Their grants are checked where the broker validates them.
func CheckIssuedCredentials(generation bootstrap.MaterialGeneration, creds []byte, now time.Time) error {
	raw, err := jwt.ParseDecoratedJWT(creds)
	if err != nil {
		return err
	}
	claims, err := jwt.DecodeUserClaims(raw)
	if err != nil {
		return err
	}
	user, err := jwt.ParseDecoratedUserNKey(creds)
	if err != nil {
		return err
	}
	public, err := user.PublicKey()
	user.Wipe()
	lifetime := time.Duration(generation.IssuedLifetimeHours) * time.Hour
	if err != nil || public != claims.Subject || claims.Issuer != generation.AccountSigner ||
		claims.IssuerAccount != generation.CellAccount || claims.Expires == 0 ||
		time.Unix(claims.IssuedAt, 0).After(now.Add(bootstrap.ManifestClockSkew)) ||
		time.Unix(claims.Expires, 0).Sub(time.Unix(claims.IssuedAt, 0)) > lifetime ||
		!now.Before(time.Unix(claims.Expires, 0)) || claims.NotBefore > now.Unix() {
		return errors.New("issued NATS credentials are not the account signer's, current and within the generation's lifetime")
	}
	return nil
}

