func New(t testing.TB, now time.Time) Material { return NewCell(t, now, "gru") }

// NewCell is New for the cell whose token is region.
func NewCell(t testing.TB, now time.Time, region string) Material {
	t.Helper()
	operator, _ := nkeys.CreateOperator()
	system, _ := nkeys.CreateAccount()
	cell, _ := nkeys.CreateAccount()
	hostSigner, _ := nkeys.CreateAccount()
	return Rollover(t, now, Material{Operator: operator, System: system, Cell: cell, HostSigner: hostSigner, Region: region})
}

// Rollover builds a new CA, issuers and account signer for the NATS
// operator, system and cell accounts and host signer of previous.
func Rollover(t testing.TB, now time.Time, previous Material) Material {
	t.Helper()
	operator, system, cell, hostSigner, region := previous.Operator, previous.System, previous.Cell, previous.HostSigner, previous.Region
	year := now.AddDate(1, 0, 0)
	ca, caPEM, _ := Certificate(t, CA("TerraScale gru controller CA", now, year), nil)
	controllerIssuer, controllerCert, controllerKey := Certificate(t, ControllerIssuer(now, year.Add(-time.Hour)), &ca)
	_, hostCert, hostKey := Certificate(t, hostIssuer(region, now, year.Add(-time.Hour)), &ca)
	signer, _ := nkeys.CreateAccount()
	operatorID, _ := operator.PublicKey()
	systemID, _ := system.PublicKey()
	cellID, _ := cell.PublicKey()
	hostSignerID, _ := hostSigner.PublicKey()
	signerID, _ := signer.PublicKey()
	signerSeed, _ := signer.Seed()
	operatorClaims := jwt.NewOperatorClaims(operatorID)
	operatorClaims.SystemAccount = systemID
	operatorJWT, err := operatorClaims.Encode(operator)
	if err != nil {
		t.Fatal(err)
	}
	systemClaims := jwt.NewAccountClaims(systemID)
	systemClaims.Expires = year.Unix()
	systemJWT, _ := systemClaims.Encode(operator)
	cellClaims := jwt.NewAccountClaims(cellID)
	cellClaims.Expires = year.Unix()
	cellClaims.Limits.JetStreamLimits = jwt.JetStreamLimits{MemoryStorage: jwt.NoLimit, DiskStorage: jwt.NoLimit,
		Streams: jwt.NoLimit, Consumer: jwt.NoLimit}
	cellClaims.SigningKeys.AddScopedSigner(bootstrapmaterial.HostScope(region, hostSignerID))
	cellClaims.SigningKeys.Add(signerID)
	cellJWT, _ := cellClaims.Encode(operator)
	user, _ := nkeys.CreateUser()
	userID, _ := user.PublicKey()
	userSeed, _ := user.Seed()
	userClaims := jwt.NewUserClaims(userID)
	userClaims.Expires = year.Unix()
	userClaims.Pub.Allow = jwt.StringList{"$SYS.REQ.ACCOUNT." + cellID + ".CLAIMS.UPDATE"}
	userClaims.Sub.Allow = jwt.StringList{protocol.InboxGrant(region, userID)}
	userJWT, _ := userClaims.Encode(system)
	systemCreds, _ := jwt.FormatUserConfig(userJWT, userSeed)
	return Material{Files: map[string][]byte{
		"ca.pem": caPEM, "operator.jwt": []byte(operatorJWT + "\n"), "system.jwt": []byte(systemJWT + "\n"),
		"cell.jwt": []byte(cellJWT + "\n"), "system.creds": systemCreds,
		"host-tls-issuer-cert.pem": hostCert, "host-tls-issuer-key.pem": hostKey,
		"controller-tls-issuer-cert.pem": controllerCert, "controller-tls-issuer-key.pem": controllerKey,
		"controller-account-signer.seed": append(signerSeed, '\n'),
	}, OperatorID: operatorID, SystemID: systemID, CellID: cellID, HostSignerID: hostSignerID, SignerID: signerID,
		Operator: operator, System: system, Cell: cell, HostSigner: hostSigner, Signer: signer, Region: region,
		CA: ca, ControllerIssuer: controllerIssuer}.withRoleSigner(t)
}

// Generation pins every file of the material under the v1 contract.
func (material Material) Generation(expected bootstrap.MaterialGenerationExpectation, number uint64, previous string,
) bootstrap.MaterialGeneration {
	generation := bootstrap.MaterialGeneration{SchemaVersion: bootstrap.MaterialGenerationSchemaVersion,
		DeploymentID: expected.DeploymentID, Environment: expected.Environment, ClusterID: expected.ClusterID,
		Cell: expected.Cell, ControllerSlots: expected.ControllerSlots, Generation: number, Previous: previous,
		Operator: material.OperatorID, SystemAccount: material.SystemID, CellAccount: material.CellID,
		HostSigner: material.HostSignerID, AccountSigner: material.SignerID, RoleSigner: material.RoleSignerID}
	if material.SignerID != "" {
		generation.IssuedLifetimeHours = 24 * 7
	}
	for _, slot := range expected.ControllerSlots {
		if data, ok := material.Files["controller-"+slot+".json"]; ok {
			generation.ControllerConfigs = append(generation.ControllerConfigs, bootstrap.GenerationControllerConfig{
				Slot: slot, AcceptanceSHA256: digest([]byte("manifest of " + slot)), SHA256: digest(data), Size: int64(len(data))})
		}
	}
	for name, data := range material.Files {
		if strings.HasSuffix(name, ".json") {
			continue
		}
		purpose, slot := bootstrap.MaterialGenerationFiles()[name], ""
		if purpose == "" {
			purpose = bootstrap.SecretInterRegion
			for _, candidate := range expected.ControllerSlots {
				if name == candidate+".creds" {
					purpose, slot = bootstrap.SecretController, candidate
				}
				if cert, key := bootstrap.InterRegionTLSFiles(candidate); name == cert || name == key {
					slot = candidate
				}
			}
		}
		generation.Secrets = append(generation.Secrets, bootstrap.SecretReference{Purpose: purpose, Slot: slot,
			SecretOCID: fmt.Sprintf("ocid1.vaultsecret.oc1.sa-saopaulo-1.g%d-%s", number,
				strings.NewReplacer(".", "-", "_", "-").Replace(name)),
			VersionNumber: 1, SHA256: digest(data), MaxBytes: bootstrap.MaxSecretBytes, TargetFile: name})
	}
	return generation
}

// WithControllerCredentials adds offline-issued, slot-bound controller users
// and points each supplied config at its own credentials.
func (material Material) WithControllerCredentials(t testing.TB, slots []string) Material {
	t.Helper()
	files := map[string][]byte{}
	for _, slot := range slots {
		name := "controller-" + slot + ".json"
		var config struct {
			Version    int             `json:"version"`
			Controller map[string]any  `json:"controller"`
			NATS       natscell.Config `json:"nats"`
		}
		data, exists := material.Files[name]
		if !exists {
			t.Fatalf("WithControllerCredentials: slot %s has no %s", slot, name)
		}
		if err := json.Unmarshal(data, &config); err != nil {
			t.Fatalf("WithControllerCredentials: decode %s: %v", name, err)
		}
		config.NATS.CredentialsFile = bootstrap.MaterialDirectory + "/" + slot + ".creds"
		var ir *natscell.InterRegion
		if embedded := config.NATS.Embedded; embedded != nil {
			ir = embedded.InterRegion
		}
		home, err := ir.GlobalControlHome(config.NATS.Cell)
		if err != nil {
			t.Fatal(err)
		}
		globalHome := home == config.NATS.Cell
		user, _ := nkeys.CreateUser()
		public, _ := user.PublicKey()
		seed, _ := user.Seed()
		claim := jwt.NewUserClaims(public)
		claim.Expires = material.CA.Certificate.NotAfter.Unix()
		claim.Pub.Allow = natscell.ControllerPublishes("gru")
		if globalHome {
			claim.Pub.Allow.Add(natscell.GlobalControllerPublishes()...)
		}
		claim.Sub.Allow = jwt.StringList{protocol.InboxGrant("gru", public), protocol.Broker("gru", "ticket", ">"),
			protocol.Broker("gru", "fence", slot)}
		claim.Sub.Allow.Add(natscell.ControllerSubscriptions("gru")...)
		claim.Sub.Allow.Add(protocol.ObservabilityGrant("gru"))
		claim.Resp = &jwt.ResponsePermission{MaxMsgs: 1, Expires: 5 * time.Second}
		raw, err := claim.Encode(material.Cell)
		if err != nil {
			t.Fatal(err)
		}
		files[slot+".creds"], _ = jwt.FormatUserConfig(raw, seed)
		files[name], err = json.Marshal(config)
		if err != nil {
			t.Fatal(err)
		}
		clear(seed)
		user.Wipe()
	}
	return material.With(files)
}

func (material Material) withRoleSigner(t testing.TB) Material {
	t.Helper()
	signer, err := roleidentity.Signer(material.HostSigner)
	if err != nil {
		t.Fatal(err)
	}
	material.RoleSignerID, _ = signer.PublicKey()
	signer.Wipe()
	return material.With(map[string][]byte{"cell.jwt": material.Account(t, "cell.jwt", func(claims *jwt.AccountClaims) {
		claims.SigningKeys.AddScopedSigner(roleidentity.Scope(material.RoleSignerID))
	})})
}

// WithoutIssuers drops the controller issuers and the account signer, as
// gru-1 and sfo-1 were founded.
func (material Material) WithoutIssuers(t testing.TB) Material {
	t.Helper()
	cell := material.Account(t, "cell.jwt", func(claims *jwt.AccountClaims) { delete(claims.SigningKeys, material.SignerID) })
	copied := material.With(map[string][]byte{"cell.jwt": cell})
	for _, name := range []string{"controller-tls-issuer-cert.pem", "controller-tls-issuer-key.pem",
		"controller-account-signer.seed"} {
		delete(copied.Files, name)
	}
	copied.SignerID, copied.Signer = "", nil
	return copied
}

// InterRegion adds cell gru's leaf fabric (TS-668) in the tree
// sfo <- gru <- fra, so gru both dials a parent and accepts a child:
// system.jwt and cell.jwt with the contract, interregion.jwt, the
// interregion CA, each slot's leaf TLS, leaf-sfo.creds and each slot's
// controller config.
func (material Material) InterRegion(t testing.TB, now time.Time, slots []string) Material {
	t.Helper()
	year := now.AddDate(1, 0, 0)
	topology := natscell.LeafTopology{Hub: "sfo", Parents: map[string]string{"gru": "sfo", "fra": "gru"}}
	contract := natscell.InterRegionContract{Cell: "gru", Peers: topology.Peers("gru"), GlobalHome: "sfo",
		Subtrees: topology.Subtrees("gru")}
	account, _ := nkeys.CreateAccount()
	accountID, _ := account.PublicKey()
	child, _ := nkeys.CreateAccount()
	childID, _ := child.PublicKey()
	interregion := jwt.NewAccountClaims(accountID)
	interregion.Expires = year.Unix()
	contract.ApplyInterRegion(interregion, material.CellID, 2, map[string]string{"fra": childID})
	interregionJWT, err := interregion.Encode(material.Operator)
	if err != nil {
		t.Fatal(err)
	}
	parent, _ := nkeys.CreateAccount()
	parentID, _ := parent.PublicKey()
	parentSigner, _ := nkeys.CreateAccount()
	user, _ := nkeys.CreateUser()
	userID, _ := user.PublicKey()
	userSeed, _ := user.Seed()
	userClaims := jwt.NewUserClaims(userID)
	userClaims.UserPermissionLimits = jwt.UserPermissionLimits{}
	userClaims.IssuerAccount = parentID
	userClaims.Expires = year.Unix()
	userJWT, err := userClaims.Encode(parentSigner)
	if err != nil {
		t.Fatal(err)
	}
	leafCreds, _ := jwt.FormatUserConfig(userJWT, userSeed)
	ca, caPEM, _ := Certificate(t, CA("TerraScale interregion CA", now, year), nil)
	files := map[string][]byte{
		"system.jwt": material.Account(t, "system.jwt", func(claims *jwt.AccountClaims) { claims.Limits.LeafNodeConn = 0 }),
		"cell.jwt": material.Account(t, "cell.jwt", func(claims *jwt.AccountClaims) {
			contract.ApplyCell(claims, accountID)
		}),
		"interregion.jwt": []byte(interregionJWT + "\n"), "interregion-ca.pem": caPEM, "leaf-sfo.creds": leafCreds,
	}
	const directory = bootstrap.MaterialDirectory + "/"
	for _, slot := range slots {
		certName, keyName := bootstrap.InterRegionTLSFiles(slot)
		_, files[certName], files[keyName] = Certificate(t, &x509.Certificate{Subject: pkix.Name{CommonName: "gru-" + slot},
			DNSNames: []string{"leaf.gru.interregion.terrascale.internal"}, NotBefore: now.Add(-time.Hour), NotAfter: year,
			KeyUsage:    x509.KeyUsageDigitalSignature,
			ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth}}, &ca)
		leafTLS := natscell.TLSFiles{CAFile: directory + "interregion-ca.pem", CertFile: directory + certName,
			KeyFile: directory + keyName}
		config, err := json.Marshal(map[string]any{"version": roleconfig.Version, "controller": map[string]any{"candidate_id": slot},
			"nats": natscell.Config{Cell: "gru", Instance: slot, Embedded: &natscell.Embedded{
				CellJWTFile: directory + "cell.jwt", SystemJWTFile: directory + "system.jwt",
				InterRegion: &natscell.InterRegion{Peers: contract.Peers, GlobalHome: "sfo",
					AccountJWTFile: directory + "interregion.jwt", Subtrees: contract.Subtrees, Topology: &topology,
					Listen: &natscell.LeafListen{Host: "0.0.0.0", Port: 7422, TLS: leafTLS},
					Remotes: []natscell.LeafRemote{{Peer: "sfo", URLs: []string{"nats-leaf://10.1.0.10:7422"},
						ServerName:      "leaf.gru.interregion.terrascale.internal",
						CredentialsFile: directory + "leaf-sfo.creds", PeerAccount: parentID, TLS: leafTLS}}}}}},
			json.Deterministic(true))
		if err != nil {
			t.Fatal(err)
		}
		files["controller-"+slot+".json"] = config
	}
	return material.With(files)
}

// Link adds the region link (TS-803): cell.jwt with the link signer, the
// interregion CA, each slot's leaf TLS and a controller config with a link
// block, and outside the home link.creds for another account.
func (material Material) Link(t testing.TB, now time.Time, slots []string) Material {
	t.Helper()
	year := now.AddDate(1, 0, 0)
	signer, _ := nkeys.CreateAccount()
	signerID, _ := signer.PublicKey()
	ca, caPEM, _ := Certificate(t, CA("TerraScale interregion CA", now, year), nil)
	files := map[string][]byte{"interregion-ca.pem": caPEM,
		"cell.jwt": material.Account(t, "cell.jwt", func(claims *jwt.AccountClaims) { natscell.ApplyLink(claims, signerID) })}
	const directory = bootstrap.MaterialDirectory + "/"
	var credentials string
	if material.Region != natscell.LinkHome {
		home, _ := nkeys.CreateAccount()
		homeID, _ := home.PublicKey()
		creds, err := natscell.IssueLinkUser(signer, homeID, material.Region, now, year)
		if err != nil {
			t.Fatal(err)
		}
		files[bootstrap.LinkCredentialsFile], credentials = creds, directory+bootstrap.LinkCredentialsFile
	}
	for _, slot := range slots {
		certName, keyName := bootstrap.InterRegionTLSFiles(slot)
		_, files[certName], files[keyName] = Certificate(t, &x509.Certificate{Subject: pkix.Name{CommonName: material.Region + "-" + slot},
			DNSNames: []string{"leaf." + material.Region + ".interregion.terrascale.internal"}, NotBefore: now.Add(-time.Hour),
			NotAfter: year, KeyUsage: x509.KeyUsageDigitalSignature,
			ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth}}, &ca)
		config, err := json.Marshal(map[string]any{"version": roleconfig.Version, "controller": map[string]any{"candidate_id": slot},
			"nats": natscell.Config{Cell: material.Region, Instance: slot, Embedded: &natscell.Embedded{
				CellJWTFile: directory + "cell.jwt", SystemJWTFile: directory + "system.jwt",
				Link: &natscell.Link{CredentialsFile: credentials, TLS: natscell.TLSFiles{CAFile: directory + "interregion-ca.pem",
					CertFile: directory + certName, KeyFile: directory + keyName}}}}}, json.Deterministic(true))
		if err != nil {
			t.Fatal(err)
		}
		files["controller-"+slot+".json"] = config
	}
	return material.With(files)
}

// Account re-signs one of the material's account JWTs after edit.
func (material Material) Account(t testing.TB, name string, edit func(*jwt.AccountClaims)) []byte {
	t.Helper()
	claims, err := jwt.DecodeAccountClaims(strings.TrimSpace(string(material.Files[name])))
	if err != nil {
		t.Fatal(err)
	}
	edit(claims)
	encoded, err := claims.Encode(material.Operator)
	if err != nil {
		t.Fatal(err)
	}
	return []byte(encoded + "\n")
}

// Read returns one file.
func (material Material) Read(name string) ([]byte, error) {
	data, ok := material.Files[name]
	if !ok {
		return nil, errors.New("missing")
	}
	return data, nil
}

// With copies the material with some files replaced.
func (material Material) With(files map[string][]byte) Material {
	copied := material
	copied.Files = map[string][]byte{}
	for name, data := range material.Files {
		copied.Files[name] = data
	}
	for name, data := range files {
		copied.Files[name] = data
	}
	return copied
}

func CheckGenerationFiles(generation bootstrap.MaterialGeneration, read func(name string) ([]byte, error), now time.Time,
) (time.Time, error) {
	if err := generation.Validate(); err != nil {
		return time.Time{}, err
	}
	files := map[string][]byte{}
	for _, secret := range generation.Secrets {
		data, err := read(secret.TargetFile)
		if secret.Slot != "" && errors.Is(err, fs.ErrNotExist) {
			continue
		}
		if err != nil {
			return time.Time{}, fmt.Errorf("read %s: %w", secret.TargetFile, err)
		}
		digest := sha256.Sum256(data)
		if int64(len(data)) > secret.MaxBytes || hex.EncodeToString(digest[:]) != secret.SHA256 {
			return time.Time{}, fmt.Errorf("%w: %s differs from its pinned digest or size",
				bootstrap.ErrMaterialGenerationInvalid, secret.TargetFile)
		}
		files[secret.TargetFile] = data
	}
	configs := map[string][]byte{}
	for _, pin := range generation.ControllerConfigs {
		name := "controller-" + pin.Slot + ".json"
		data, err := read(name)
		if errors.Is(err, fs.ErrNotExist) {
			continue
		}
		if err != nil {
			return time.Time{}, fmt.Errorf("read %s: %w", name, err)
		}
		if int64(len(data)) != pin.Size || digest(data) != pin.SHA256 {
			return time.Time{}, fmt.Errorf("%w: %s differs from its pinned digest or size",
				bootstrap.ErrMaterialGenerationInvalid, name)
		}
		configs[pin.Slot] = data
	}
	cell := strings.ToLower(string(generation.Cell))
	check := generationCheck{now: now}
	roots := check.bundle("ca.pem", files["ca.pem"])
	// The v1 contract may pin no controller issuers; Validate ties them to
	// AccountSigner.
	issuing := generation.AccountSigner != ""
	if issuing {
		check.controllerIssuers(generation, files, roots)
	}
	if _, issuer, _, err := hostenroll.ParseTLSIssuer(files["host-tls-issuer-key.pem"], files["host-tls-issuer-cert.pem"],
		roots); err != nil {
		check.fail(err.Error())
	} else {
		domain := "hosts." + cell + ".terrascale.internal"
		if !issuer.PermittedDNSDomainsCritical || !slices.Equal(issuer.PermittedDNSDomains, []string{"." + domain}) ||
			!slices.Equal(issuer.PermittedURIDomains, []string{domain}) {
			check.fail("the host TLS issuer is not constrained to the cell's hosts")
		}
		check.certificate("host-tls-issuer-cert.pem", issuer)
	}
	operator, err := jwt.DecodeOperatorClaims(strings.TrimSpace(string(files["operator.jwt"])))
	// Decoding verifies each signature against the claim's issuer; the
	// issuer checks and DidSign tie those signers to the operator.
	if err != nil || operator.Subject != generation.Operator || operator.Issuer != generation.Operator ||
		!operator.DidSign(operator) || operator.SystemAccount != generation.SystemAccount || len(operator.SigningKeys) != 0 {
		check.fail("operator.jwt is not the operator's own JWT naming the system account, without signing keys")
		operator = nil
	} else {
		check.jwt("operator.jwt", operator.IssuedAt, operator.Expires)
	}
	system, err := jwt.DecodeAccountClaims(strings.TrimSpace(string(files["system.jwt"])))
	if err != nil || system.Subject != generation.SystemAccount || system.Issuer != generation.Operator ||
		operator == nil || !operator.DidSign(system) {
		check.fail("system.jwt is not the system account signed by the operator")
		system = nil
	} else {
		check.jwt("system.jwt", system.IssuedAt, system.Expires)
	}
	cellClaim, err := jwt.DecodeAccountClaims(strings.TrimSpace(string(files["cell.jwt"])))
	if err != nil || cellClaim.Subject != generation.CellAccount || cellClaim.Issuer != generation.Operator ||
		operator == nil || !operator.DidSign(cellClaim) {
		check.fail("cell.jwt is not the cell account signed by the operator")
		cellClaim = nil
	} else {
		hostScope, hostScoped := cellClaim.SigningKeys.GetScope(generation.HostSigner)
		keys := hostScoped && reflect.DeepEqual(hostScope, expectedHostScope(cell, generation.HostSigner))
		if issuing {
			accountScope, accountSigner := cellClaim.SigningKeys.GetScope(generation.AccountSigner)
			keys = keys && accountSigner && accountScope == nil
		}
		if generation.RoleSigner != "" {
			roleScope, roleScoped := cellClaim.SigningKeys.GetScope(generation.RoleSigner)
			keys = keys && roleScoped && reflect.DeepEqual(roleScope, roleidentity.Scope(generation.RoleSigner))
		}
		linked := natscell.VerifyLinkScope(cellClaim) == nil
		if !keys || len(cellClaim.SigningKeys) != 1+boolInt(issuing)+boolInt(generation.RoleSigner != "")+boolInt(linked) {
			check.fail("cell.jwt must have exactly the host scope, in v1 the role scope, with controller " +
				"issuers the unscoped account signer, and a link's signer as signing keys")
		}
		if cellClaim.Limits.JetStreamLimits == (jwt.JetStreamLimits{}) {
			check.fail("cell.jwt grants no JetStream")
		}
		check.jwt("cell.jwt", cellClaim.IssuedAt, cellClaim.Expires)
	}
	if err := natscell.ValidateSystemCredentials(files["system.creds"], cell, generation.CellAccount,
		generation.SystemAccount); err != nil {
		check.fail(err.Error())
	} else if raw, err := jwt.ParseDecoratedJWT(files["system.creds"]); err == nil {
		if user, err := jwt.DecodeUserClaims(raw); err == nil {
			check.jwt("system.creds", user.IssuedAt, user.Expires)
		}
	}
	check.interRegion(generation, files, configs, operator, system, cellClaim)
	if len(check.problems) != 0 {
		return time.Time{}, fmt.Errorf("%w: %s", bootstrap.ErrMaterialGenerationInvalid, strings.Join(check.problems, "; "))
	}
	return check.first, nil
}

func (check *generationCheck) controllerConfig(generation bootstrap.MaterialGeneration, slot string, data []byte,
	files map[string][]byte, pinned map[string]bool, leafAccounts map[string]string, system, cellClaim, interregion *jwt.AccountClaims,
) bool {
	name := "controller-" + slot + ".json"
	var top map[string]jsontext.Value
	var version int
	var nats natscell.Config
	if protocol.DecodeStrict(data, &top, bootstrap.MaxControllerConfigBytes) != nil ||
		protocol.DecodeStrict(top["version"], &version, bootstrap.MaxControllerConfigBytes) != nil || version != roleconfig.Version || top["controller"] == nil ||
		top["nats"] == nil || protocol.DecodeStrict(top["nats"], &nats, bootstrap.MaxControllerConfigBytes) != nil {
		check.fail(name + " is not a controller config")
		return false
	}
	if data := top["observability"]; data != nil {
		var telemetry observability.Config
		if protocol.DecodeStrict(data, &telemetry, bootstrap.MaxControllerConfigBytes) != nil || telemetry.Validate() != nil {
			check.fail(name + " has invalid observability settings")
			return false
		}
	}
	var ir *natscell.InterRegion
	var link *natscell.Link
	if nats.Embedded != nil {
		ir, link = nats.Embedded.InterRegion, nats.Embedded.Link
	}
	home, err := ir.GlobalControlHome(nats.Cell)
	if err != nil {
		check.fail(name + " has an invalid global home: " + err.Error())
		return false
	}
	if link != nil {
		home = natscell.LinkHome
	}
	var controller map[string]jsontext.Value
	if protocol.DecodeStrict(top["controller"], &controller, bootstrap.MaxControllerConfigBytes) != nil {
		check.fail(name + " has no controller settings")
		return false
	}
	if data := controller["global"]; data != nil {
		var global struct {
			Home string `json:"home"`
		}
		if protocol.DecodeStrict(data, &global, bootstrap.MaxControllerConfigBytes) != nil {
			check.fail(name + " has invalid global controller settings")
			return false
		}
		if global.Home != "" && global.Home != home {
			check.fail(name + " has a global home inconsistent with its interregion topology")
			return false
		}
	}
	if credsName := slot + ".creds"; pinned[credsName] {
		if nats.Cell != strings.ToLower(string(generation.Cell)) || nats.Instance != slot ||
			nats.CredentialsFile != filepath.Join(bootstrap.MaterialDirectory, credsName) || files[credsName] == nil {
			check.fail(credsName + " must be present and referenced at its installed path by its own cell and slot's config")
			return false
		}
		if err := CheckControllerCredentials(files[credsName], nats.Cell, slot, generation.CellAccount); err != nil {
			check.fail(credsName + ": " + err.Error())
		} else if raw, err := jwt.ParseDecoratedJWT(files[credsName]); err == nil {
			claim, err := jwt.DecodeUserClaims(raw)
			if err != nil {
				check.fail(credsName + ": " + err.Error())
			} else {
				check.jwt(credsName, claim.IssuedAt, claim.Expires)
			}
		}
		if home == nats.Cell {
			if err := natscell.ValidateGlobalControllerCredentialBytes(files[credsName]); err != nil {
				check.fail(credsName + ": " + err.Error())
			}
		}
	}
	if (ir != nil) != pinned["interregion.jwt"] || (link != nil) != (pinned["interregion-ca.pem"] && !pinned["interregion.jwt"]) {
		check.fail(name + " must reference interregion or link material exactly when the generation pins its files")
		return false
	} else if link != nil {
		return check.link(generation, slot, name, nats, pinned, cellClaim)
	} else if ir == nil {
		return false
	}
	contract, links, err := ir.Contract(nats.Cell)
	if err != nil || nats.Cell != strings.ToLower(string(generation.Cell)) {
		check.fail(name + " has no valid interregion block for this cell")
		return false
	}
	if system != nil && cellClaim != nil && interregion != nil {
		if err := contract.VerifyClaims(system, cellClaim, interregion, links); err != nil {
			check.fail("system.jwt, cell.jwt and interregion.jwt fail the interregion contract of " + name + ": " + err.Error())
		}
	}
	cert, key := bootstrap.InterRegionTLSFiles(slot)
	file := func(path, want string) bool {
		return path == filepath.Join(bootstrap.MaterialDirectory, want) && pinned[want]
	}
	tlsFiles := func(files natscell.TLSFiles) bool {
		return file(files.CAFile, "interregion-ca.pem") && file(files.CertFile, cert) && file(files.KeyFile, key)
	}
	pinnedOnly := file(ir.AccountJWTFile, "interregion.jwt") && file(nats.Embedded.CellJWTFile, "cell.jwt") &&
		file(nats.Embedded.SystemJWTFile, "system.jwt") && (ir.Listen == nil || tlsFiles(ir.Listen.TLS))
	dialed := map[string]bool{}
	for _, remote := range ir.Remotes {
		creds := "leaf-" + remote.Peer + ".creds"
		pinnedOnly = pinnedOnly && tlsFiles(remote.TLS) && file(remote.CredentialsFile, creds) &&
			remote.PeerAccount == leafAccounts[creds]
		dialed[creds] = true
	}
	for creds := range leafAccounts {
		pinnedOnly = pinnedOnly && dialed[creds]
	}
	if !pinnedOnly {
		check.fail(name + "'s interregion block references a file this generation does not pin, " +
			"or a remote account that did not issue its credentials")
	}
	return true
}

// link checks one config's link block: only pinned files, by absolute path,
// the slot's own leaf TLS, link.creds exactly on a spoke, and on the home a
// cell.jwt that carries the link signer.
func (check *generationCheck) link(generation bootstrap.MaterialGeneration, slot, name string, nats natscell.Config,
	pinned map[string]bool, cellClaim *jwt.AccountClaims,
) bool {
	if nats.Cell != strings.ToLower(string(generation.Cell)) {
		check.fail(name + " has no valid link block for this cell")
		return false
	}
	file := func(path, want string) bool {
		return path == filepath.Join(bootstrap.MaterialDirectory, want) && pinned[want]
	}
	link := nats.Embedded.Link
	cert, key := bootstrap.InterRegionTLSFiles(slot)
	credentials := link.CredentialsFile == "" && !pinned[bootstrap.LinkCredentialsFile]
	if nats.Cell != natscell.LinkHome {
		credentials = file(link.CredentialsFile, bootstrap.LinkCredentialsFile)
	}
	if !credentials || !file(link.TLS.CAFile, "interregion-ca.pem") || !file(link.TLS.CertFile, cert) ||
		!file(link.TLS.KeyFile, key) || !file(nats.Embedded.CellJWTFile, "cell.jwt") || !file(nats.Embedded.SystemJWTFile, "system.jwt") {
		check.fail(name + "'s link block references a file this generation does not pin, or link credentials on the home")
	}
	if nats.Cell == natscell.LinkHome && cellClaim != nil {
		if err := natscell.VerifyLinkScope(cellClaim); err != nil {
			check.fail("cell.jwt fails the link home check of " + name + ": " + err.Error())
		}
	}
	return true
}

// controllerIssuer checks the controller TLS issuer: a single EC key and
// certificate that match, a path-length-zero intermediate for server and
// client leaves, signed by a CA in roots and not itself one of them.

func SignMaterialGeneration(generation MaterialGeneration, issuedAt, expiresAt time.Time, rootPrivateKey ed25519.PrivateKey,
) (trust.Envelope, error) {
	if err := generation.Validate(); err != nil {
		return trust.Envelope{}, err
	}
	payload, err := trust.EncodePayload(generation)
	if err != nil {
		return trust.Envelope{}, err
	}
	if len(payload) > MaxMaterialGenerationBytes {
		return trust.Envelope{}, fmt.Errorf("%w: generation exceeds its size limit", ErrMaterialGenerationInvalid)
	}
	if expiresAt.Sub(issuedAt) > MaxMaterialGenerationLifetime {
		return trust.Envelope{}, fmt.Errorf("%w: validity exceeds %s", ErrMaterialGenerationInvalid, MaxMaterialGenerationLifetime)
	}
	return trust.Sign(payload, materialGenerationScope(generation.DeploymentID, string(generation.Cell), generation.Environment),
		issuedAt, expiresAt, rootPrivateKey)
}

// VerifyMaterialGenerationChain verifies a chain, oldest first, for the
// expected deployment: every link and fixed key, and the newest generation's
// root signature as current at now. Use the current roots: a chain extended
// by a retired root is refused.
func VerifyMaterialGenerationChain(chain []trust.Envelope, roots trust.Keyring, expected MaterialGenerationExpectation,
	now time.Time,
) ([]VerifiedMaterialGeneration, error) {
	return verifyMaterialGenerationChain(chain, expected, func(envelope trust.Envelope, scope trust.Scope) ([]byte, error) {
		return trust.VerifyCurrent(envelope, scope, roots, now, MaterialGenerationPolicy())
	})
}

// VerifyAdoptedMaterialGenerationChain is VerifyMaterialGenerationChain
// without the current-time check, for a controller restarting on a chain it
// adopted; roots may include ones rotated out since.
func VerifyAdoptedMaterialGenerationChain(chain []trust.Envelope, roots trust.Keyring,
	expected MaterialGenerationExpectation,
) ([]VerifiedMaterialGeneration, error) {
	return verifyMaterialGenerationChain(chain, expected, func(envelope trust.Envelope, scope trust.Scope) ([]byte, error) {
		return trust.VerifyHistorical(envelope, scope, roots, MaterialGenerationPolicy())
	})
}

func verifyMaterialGenerationChain(chain []trust.Envelope, expected MaterialGenerationExpectation,
	verifyNewest func(trust.Envelope, trust.Scope) ([]byte, error),
) ([]VerifiedMaterialGeneration, error) {
	if len(chain) == 0 || len(chain) > MaxMaterialGenerations {
		return nil, fmt.Errorf("%w: chain length", ErrMaterialGenerationInvalid)
	}
	scope := materialGenerationScope(expected.DeploymentID, string(expected.Cell), expected.Environment)
	newest := chain[len(chain)-1]
	if _, err := verifyNewest(newest, scope); err != nil {
		return nil, fmt.Errorf("verify material generation signature: %w", err)
	}
	verified := make([]VerifiedMaterialGeneration, 0, len(chain))
	for index, envelope := range chain {
		if envelope.Scope != scope {
			return nil, fmt.Errorf("%w: generation scope", ErrMaterialGenerationInvalid)
		}
		var generation MaterialGeneration
		if err := protocol.DecodeStrict(envelope.Payload, &generation, MaxMaterialGenerationBytes); err != nil {
			return nil, fmt.Errorf("%w: %v", ErrMaterialGenerationInvalid, err)
		}
		if err := generation.Validate(); err != nil {
			return nil, err
		}
		if !expected.matches(generation) || generation.Generation != uint64(index+1) {
			return nil, fmt.Errorf("%w: generation %d does not belong at position %d of this deployment's chain",
				ErrMaterialGenerationInvalid, generation.Generation, index+1)
		}
		if index > 0 {
			previous := verified[index-1]
			// Never drop a pinned config: controllers would
			// restart on configs the effective manifest no longer pins.
			if generation.Previous != previous.fingerprint || generation.Operator != previous.generation.Operator ||
				generation.SystemAccount != previous.generation.SystemAccount ||
				generation.CellAccount != previous.generation.CellAccount ||
				generation.HostSigner != previous.generation.HostSigner ||
				generation.RoleSigner != previous.generation.RoleSigner ||
				len(previous.generation.ControllerConfigs) != 0 && len(generation.ControllerConfigs) == 0 ||
				slices.ContainsFunc(previous.generation.Secrets, func(ref SecretReference) bool { return ref.Purpose == SecretController }) &&
					!slices.ContainsFunc(generation.Secrets, func(ref SecretReference) bool { return ref.Purpose == SecretController }) {
				return nil, fmt.Errorf("%w: generation %d does not extend generation %d", ErrMaterialGenerationInvalid,
					generation.Generation, previous.generation.Generation)
			}
		}
		fingerprint, err := trust.Fingerprint(envelope)
		if err != nil {
			return nil, err
		}
		verified = append(verified, VerifiedMaterialGeneration{generation: generation, fingerprint: fingerprint,
			expiresAt: envelope.ExpiresAt})
	}
	return verified, nil
}

// ExtendsMaterialGenerationChain reports whether chain holds every
// generation of base, byte for byte, and at least one more.
func ExtendsMaterialGenerationChain(chain, base []trust.Envelope) bool {
	if len(chain) <= len(base) {
		return false
	}
	if len(base) == 0 {
		return true
	}
	prefix, err := EncodeMaterialGenerationChain(chain[:len(base)])
	held, heldErr := EncodeMaterialGenerationChain(base)
	return err == nil && heldErr == nil && string(prefix) == string(held)
}

// MaterialGenerationPayload decodes and validates a generation's payload
// without verifying its signature, for code whose caller verified the chain.
func MaterialGenerationPayload(envelope trust.Envelope) (MaterialGeneration, error) {
	var generation MaterialGeneration
	if err := protocol.DecodeStrict(envelope.Payload, &generation, MaxMaterialGenerationBytes); err != nil {
		return MaterialGeneration{}, fmt.Errorf("%w: %v", ErrMaterialGenerationInvalid, err)
	}
	if err := generation.Validate(); err != nil {
		return MaterialGeneration{}, err
	}
	return generation, nil
}

// EncodeMaterialGenerationChain emits a chain, oldest first, as one canonical
// JSON array of envelopes.
func EncodeMaterialGenerationChain(chain []trust.Envelope) ([]byte, error) {
	if len(chain) == 0 || len(chain) > MaxMaterialGenerations {
		return nil, fmt.Errorf("%w: chain length", ErrMaterialGenerationInvalid)
	}
	parts := make([]string, 0, len(chain))
	for _, envelope := range chain {
		encoded, err := trust.EncodeEnvelope(envelope)
		if err != nil {
			return nil, err
		}
		parts = append(parts, string(encoded))
	}
	return []byte("[" + strings.Join(parts, ",") + "]"), nil
}

// DecodeMaterialGenerationChain strictly decodes a canonical chain.
func DecodeMaterialGenerationChain(wire []byte) ([]trust.Envelope, error) {
	var chain []trust.Envelope
	if err := protocol.DecodeStrict(wire, &chain, MaxMaterialGenerations*(MaxMaterialGenerationBytes+16<<10)); err != nil {
		return nil, fmt.Errorf("%w: %v", ErrMaterialGenerationInvalid, err)
	}
	canonical, err := EncodeMaterialGenerationChain(chain)
	if err != nil {
		return nil, err
	}
	if string(canonical) != string(wire) {
		return nil, fmt.Errorf("%w: chain JSON is not canonical", ErrMaterialGenerationInvalid)
	}
	return chain, nil
}

